&reftitle.description;
public boolPDOStatement::bindValue stringintparam mixedvalue inttypePDO::PARAM_STR
Associa un valore al segnaposto con nome o con punto interrogativo corrispondente nell'istruzione SQL usata per preparare lo statement.

  &reftitle.examples;
  Esecuzione di un prepared statement con segnaposto con nome


<?php
/* Esegue una prepared statement associando variabili PHP */
$calories = 150;
$colour = 'red';
$sth = $dbh->prepare('SELECT name, colour, calories
    FROM fruit
    WHERE calories < :calories AND colour = :colour');

/* Imposta il valore di un parametro usando il suo nome */
$sth->bindValue('calories', $calories, PDO::PARAM_INT);
/* Facoltativamente, anche i nomi dei parametri possono avere il prefisso dei due punti ":" */
$sth->bindValue(':colour', $colour, PDO::PARAM_STR);
$sth->execute();
?>




  Esecuzione di un prepared statement con segnaposto con punto interrogativo


<?php
/* Esegue una prepared statement associando variabili PHP */
$calories = 150;
$colour = 'red';
$sth = $dbh->prepare('SELECT name, colour, calories
    FROM fruit
    WHERE calories < ? AND colour = ?');
$sth->bindValue(1, $calories, PDO::PARAM_INT);
$sth->bindValue(2, $colour, PDO::PARAM_STR);
$sth->execute();
?>
